arguments.new_str:
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public static class ModelTrainingService
{
    public static void TrainAndSaveModel(string dataPath, string modelPath)
    {
        var mlContext = new MLContext(seed: 42);

        // Load data
        var data = mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Split data for evaluation
        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Build pipeline: combine text features + priority, then classify
        var pipeline = mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketInput.Subject))
            .Append(mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label"))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Train on split for evaluation
        var model = pipeline.Fit(split.TrainSet);
        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        Console.WriteLine("=== Model Evaluation Metrics ===");
        Console.WriteLine($"  Macro Accuracy:     {metrics.MacroAccuracy:F4}");
        Console.WriteLine($"  Micro Accuracy:     {metrics.MicroAccuracy:F4}");
        Console.WriteLine($"  Log Loss:           {metrics.LogLoss:F4}");
        Console.WriteLine($"  Log Loss Reduction: {metrics.LogLossReduction:F4}");
        Console.WriteLine($"  Confusion Matrix:\n{metrics.ConfusionMatrix.GetFormattedConfusionTable()}");

        // Train on full dataset for production model
        var productionModel = pipeline.Fit(data);
        mlContext.Model.Save(productionModel, data.Schema, modelPath);
        Console.WriteLine($"Model saved to {modelPath}");
    }
}

