using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
ModelTrainingService.TrainAndSaveModel(dataPath, modelPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

